const panel=document.getElementById('learning'),content=document.getElementById('learning-content'),message=document.getElementById('learning-message');
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(text,fn,cls='')=>{const b=el('button',text,cls);b.type='button';b.onclick=()=>Promise.resolve().then(fn).catch(e=>say(e.message,true));return b;};
const say=(text,error=false)=>{message.textContent=text;message.classList.toggle('error',error);};
let current=null,saved=null,draft=null,phase='edit',dirty=false,working=false,pending=null;
async function api(path,body){const r=await fetch(path,{cache:'no-store',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const value=await r.json();if(!r.ok)throw Error(value.error||'That didn’t work. Please try again.');return value;}
function field(text,input){const label=el('label',text);label.append(input);return label;}
function pick(values,value,change){const s=el('select');for(const [id,text] of values){const o=el('option',text);o.value=id;s.append(o);}s.value=value;s.onchange=()=>change(s.value);return s;}
function change(){dirty=true;saved=null;}
function initialize(row){current=row;saved=null;dirty=false;draft={answer:row.result.answer,pins:row.result.scene.places.map(({id,name,role})=>({id,name:name||id,role})),response_kind:row.result.response_kind,static_access:row.result.static_access,note:'',reason:'wrong_place',scope:'trip'};phase='edit';draw();}
async function loadInteraction(id){initialize(await api('/api/learning/interactions/'+encodeURIComponent(id)));say('');}
function loadSaved(row){current={interaction_id:row.interaction_id,question:row.original.question,result:row.original.result,evidence:row.original.evidence,replay:row.original.replay};draft={...row.target,pins:row.resolved_target_scene.places.map(p=>({...p})),note:row.note,reason:row.reason,scope:row.scope};saved=row;dirty=false;phase='progress';draw();say('');}
function sources(){const d=el('details',null,'learning-sources');d.append(el('summary','Check the travel sources'));d.append(el('p','These are dated travel notes, not a check of today’s lifts or opening hours.','learning-muted'));for(const f of current.evidence?.facts||[])d.append(el('p',f.text));for(const s of current.evidence?.sources||[]){const a=el('a',s.title||s.id);a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';d.append(a,el('small','Checked '+s.retrieved_at.slice(0,10)));}return d;}
function steps(){const list=el('ol',null,'correction-steps');[['edit','1','Fix'],['review','2','Check'],['progress','3','Follow']].forEach(([id,n,name])=>{const item=el('li',null,phase===id?'active':'');item.append(el('span',n),el('b',name));list.append(item);});return list;}
function preview(value){if(!globalThis.homewardPreviewAnswer)throw Error('The map is still loading. Give it a moment.');globalThis.homewardPreviewAnswer(value);}
async function previewSaved(){preview(await api('/api/learning/corrections/'+saved.id+'/preview',{}));}
async function save(){if(!draft.note.trim())throw Error('Tell Homeward what it got wrong in a few words.');saved=await api('/api/learning/corrections',{interaction_id:current.interaction_id,answer:draft.answer,scene:{camera:draft.pins.length>1?'fit':draft.pins.length?'focus':'keep',places:draft.pins.map(({id,role})=>({id,role}))},response_kind:draft.response_kind,static_access:draft.static_access,reason:draft.reason,note:draft.note,scope:draft.scope});dirty=false;await history();}
function pinsEditor(){const list=el('div',null,'pin-chips');for(const p of draft.pins){const chip=el('div',null,'pin-chip');chip.append(el('span',p.name));const remove=button('×',()=>{draft.pins=draft.pins.filter(v=>v.id!==p.id);change();drawPins();},'pin-remove');remove.setAttribute('aria-label','Remove '+p.name);chip.append(remove);list.append(chip);}if(!draft.pins.length)list.append(el('p','No places selected.','learning-muted'));return list;}
function drawPins(){document.getElementById('corrected-pins').replaceChildren(pinsEditor());}
function edit(){content.append(el('h3','What should Homeward say?','learning-title'));const answer=el('textarea');answer.id='corrected-answer';answer.rows=5;answer.maxLength=3000;answer.value=draft.answer;answer.setAttribute('aria-label','Better answer');answer.oninput=()=>{draft.answer=answer.value;change();};content.append(answer);
 const old=el('details');old.append(el('summary','See the original answer'),el('p',current.result.answer));content.append(old);
 content.append(el('h3','Which places belong on the map?'));const box=el('div');box.id='corrected-pins';box.append(pinsEditor());content.append(box);
 const search=el('input');search.type='search';search.placeholder='Add a station or place…';search.setAttribute('aria-label','Add a place');const found=el('div',null,'place-results');let serial=0;
 search.oninput=async()=>{const n=++serial;found.replaceChildren();if(search.value.trim().length<2)return;try{const result=await api('/api/places?q='+encodeURIComponent(search.value));if(n!==serial)return;const available=result.places.filter(p=>!draft.pins.some(v=>v.id===p.id));if(!available.length)found.append(el('p','No more matching places. Try a different name.','learning-muted'));for(const p of available)found.append(button(p.name+(p.lines.length?' · '+p.lines.join(', '):''),()=>{if(draft.pins.length>=6)throw Error('Choose up to six places.');draft.pins.push({...p,role:'context'});change();drawPins();search.value='';found.replaceChildren();},'place-result'));}catch(e){say(e.message,true);}};content.append(search,found);
 const why=el('textarea');why.rows=2;why.maxLength=1000;why.placeholder='For example: Canary Wharf is nowhere near this meeting.';why.value=draft.note;why.oninput=()=>{draft.note=why.value;change();};content.append(field('What did it get wrong?',why));
 const reusable=el('input');reusable.type='checkbox';reusable.checked=draft.scope==='reusable';reusable.onchange=()=>{draft.scope=reusable.checked?'reusable':'trip';change();};content.append(field('Help Homeward answer this better for everyone',reusable),el('p','Leave this off for personal preferences. Trip-only edits are not sent as teaching. Your original question still goes through Mubit.','learning-muted'));
 const advanced=el('details');advanced.append(el('summary','More options'),field('Type of mistake',pick([['wrong_place','Wrong place'],['unsupported_fact','Wrong fact'],['missed_requirement','Missed something I asked for'],['unnecessary_refusal','Wouldn’t answer'],['other','Something else']],draft.reason,v=>{draft.reason=v;change();})),field('Answer type',pick([['answer','Answer'],['clarify','Ask a question'],['live_check','Check live lifts'],['outside_scope','Cannot help']],draft.response_kind,v=>{draft.response_kind=v;change();})),field('Step-free station access',pick(['not_applicable','yes','no','partial','unknown'].map(v=>[v,v.replaceAll('_',' ')]),draft.static_access,v=>{draft.static_access=v;change();})));
 for(const p of draft.pins)advanced.append(field(p.name,pick([['context','Show this place'],['origin','Start here'],['destination','Go here']],p.role,v=>{p.role=v;change();})));content.append(advanced,sources());
 content.append(button('Preview my changes',async()=>{await save();await previewSaved();phase='review';draw();say('Your edit is on the map. Homeward has not learned it yet.');},'learning-primary'));
}
function review(){content.append(el('h3','Does this look right?','learning-title'),el('p',draft.answer,'answer-review'));const places=el('div',null,'pin-chips');for(const p of draft.pins)places.append(el('span',p.name,'pin-chip'));content.append(places,el('p','Your changes are saved. The map shows your edit, not a new answer from the model.','learning-muted'),sources());
 const actions=el('div',null,'learning-actions');actions.append(button('Keep editing',()=>{phase='edit';draw();},'quiet'));
 if(draft.scope==='trip'){actions.append(button('Keep for this trip',()=>{phase='progress';draw();say('Saved for this trip. It won’t change answers for other people.');},'learning-primary'));content.append(actions);return;}
 if(saved.status!=='saved'){actions.append(button('See learning progress',()=>{phase='progress';draw();},'learning-primary'));content.append(actions);return;}
 const checked=el('input');checked.type='checkbox';const send=button('Send correction',submit,'learning-primary');send.disabled=true;checked.onchange=()=>send.disabled=!checked.checked;content.append(field('I’ve checked the answer and the places on the map',checked),el('p','Luna will check your correction, then send a teaching example to Mubit. This uses up to two model calls.','learning-muted'));actions.append(send);content.append(actions);
}
async function submit(){if(!saved||dirty)throw Error('Preview your changes before sending them.');working=true;content.inert=true;document.getElementById('learning-history').inert=true;say('Checking your correction…');try{saved=await api('/api/learning/corrections/'+saved.id+'/teach',{reviewed:true});phase='progress';draw();say(saved.error?'Your correction needs a closer look. See the details below.':'');await history();}finally{working=false;content.inert=false;document.getElementById('learning-history').inert=false;if(pending){const id=pending;pending=null;content.append(button('Fix the latest answer',()=>loadInteraction(id),'quiet'));}}}
function progress(){const r=saved,review=r.stages.mubit_review.state,sent=Boolean(r.teaching?.receipt),stored=r.stages.mubit_recording.content_stored_verified,trip=r.scope==='trip';
 const title=trip?'Saved for your trip':review==='kept'?'Ready for training':review==='rated_good'?'Waiting for a model update':review==='rejected'?'This needs another look':sent?'Your correction is with Mubit':r.teaching?.audit?.accepted===false?'Let’s check this again':'Your correction is saved';
 const body=trip?'This edit stays in your trip. It won’t teach Homeward for everyone.':review==='kept'?'Mubit has accepted this example. We still need a new model and a test on different questions.':review==='rated_good'?`We marked your correction as good in Mubit. Its training pool has ${r.platform_observation?.task_kept_examples||'unreported'} kept examples. We’re waiting for a new model so we can see whether it helped.`:review==='rejected'?'Mubit did not accept this example. You can edit it after checking the sources.':stored?'Mubit has saved the corrected reply under Homeward. It is being reviewed before training.':sent?'The teaching call reached Mubit. We still need to check that it accepted the example for training.':r.teaching?.audit?.accepted===false?'The travel notes did not support the whole correction. Check the sources and edit it.':'Preview your changes, then choose whether to send this as a shared correction.';
 content.append(el('div',null,'learning-spark'));content.append(el('h3',title,'learning-title'),el('p',body,'learning-explanation'));
 if(!trip){const list=el('ol',null,'journey-status');const rows=[['Sent to Mubit',stored?'Received and saved':sent?'Delivered':'Not sent',sent],['Reviewed in Mubit',review==='kept'?'Accepted':review==='rated_good'?'Marked good':review==='rejected'?'Not accepted':review==='pending'?'Under review':'Not confirmed',['kept','rated_good'].includes(review)],['Updated model ready',r.stages.model_update.newer_version_observed?'A new version was seen; checks needed':'Waiting for a new model',false],['Better on new questions','Not tested yet',false]];for(const [name,status,done] of rows){const li=el('li',null,done?'done':'');li.append(el('span',done?'✓':'○','journey-dot'),el('div',name),el('small',status));list.append(li);}content.append(list);}
 const actions=el('div',null,'learning-actions');actions.append(button('Show my correction',previewSaved,'quiet'),button('Edit correction',()=>{phase='edit';draw();},'quiet'));if(!trip)actions.append(button('Refresh progress',async()=>{saved=await api('/api/learning/corrections/'+r.id);draw();say('Showing our last checked Mubit status. Open Mubit for live progress.');},'quiet'));content.append(actions);
 const observed=r.platform_observation;if(observed?.fresh_development_baseline){const b=observed.fresh_development_baseline;content.append(el('p',`On ${b.cases} new test questions, v${b.version} gave ${b.valid_answer_and_map} usable answer and map. One test was interrupted. The new model hasn’t been tested yet.`,'learning-muted'));}content.append(el('p',observed?'Last checked in Mubit: '+new Date(observed.checked_at).toLocaleString()+'.':'Mubit’s acceptance has not been checked yet.','learning-muted'));const details=el('details',null,'learning-proof');details.append(el('summary','How we know'),el('p','Sending a correction is only the start. We won’t say it learned until an updated model answers different questions better.'));
 if(r.teaching?.audit)details.append(el('p','Luna’s check: '+r.teaching.audit.reason));if(r.teaching?.receipt)details.append(el('p','Mubit delivery reference'),el('code',r.teaching.receipt));if(observed)details.append(el('p',observed.review_note));if(r.error)details.append(el('p',r.error,'error'));
 const model=r.stages.model_update;details.append(el('p','Latest model we observed: '+(model.latest_observed_version?'v'+model.latest_observed_version:'unknown')+'. This correction is not linked to a completed model update.'));
 if(r.teaching?.output){const raw=el('details');raw.append(el('summary','See the teaching reply'),el('p','Luna had your target in its prompt. Copying it is not evidence of learning.'),el('pre',r.teaching.output));details.append(raw);}const a=el('a','View this in Mubit ↗');a.href=r.console_url;a.target='_blank';a.rel='noopener noreferrer';details.append(a);content.append(details);
}
function draw(){content.replaceChildren();panel.querySelector('section').scrollTop=0;document.getElementById('learning-heading').textContent=!current?'Help Homeward learn.':phase==='edit'?'Let’s fix that.':phase==='review'?'One last look.':'Your correction.';if(!current){content.append(el('p','If an answer or a place looks wrong, you can put it right.','learning-explanation'),button('Try correcting an example',async()=>{const r=await api('/api/learning/replay',{});await loadInteraction(r.interaction_id);preview(r);panel.open=true;},'learning-primary'));return;}content.append(steps());if(phase==='progress'){const context=el('details');context.append(el('summary','About this correction'),el('p',current.question));content.append(context);}else content.append(el('p',current.replay?'A REAL EARLIER ANSWER':'YOUR QUESTION','learning-tag'),el('p',current.question,'learning-question'));if(phase==='edit')edit();else if(phase==='review')review();else progress();panel.querySelector('section').scrollTop=0;}
async function history(){const box=document.getElementById('learning-history');box.replaceChildren();const rows=(await api('/api/learning')).corrections;if(!rows.length)box.append(el('p','Your corrections will appear here.','learning-muted'));for(const row of rows){const status=row.scope==='trip'?'Saved for your trip':row.stages.mubit_review.state==='kept'?'Ready for training':row.teaching?.receipt?'Sent to Mubit':'Saved';box.append(button(row.original.question+' · '+status,()=>loadSaved(row),'history-row'));}return rows;}
document.getElementById('learning-close').onclick=()=>panel.open=false;
panel.addEventListener('toggle',()=>{if(panel.open)history().then(rows=>{if(!current&&rows.length)loadSaved(rows[0]);}).catch(e=>say(e.message,true));});
window.addEventListener('homeward:answer',event=>{if(!event.detail.interaction_id)return;if(working||dirty){pending=event.detail.interaction_id;if(!working){say('A new answer is ready. Your current edit is still here.');content.append(button('Leave this edit and fix the latest answer',()=>{const id=pending;pending=null;return loadInteraction(id);},'quiet'));}return;}loadInteraction(event.detail.interaction_id).catch(e=>say(e.message,true));});
const reveal=()=>{if(document.documentElement.dataset.homewardReady==='true'){panel.hidden=false;observer.disconnect();}};const observer=new MutationObserver(reveal);observer.observe(document.documentElement,{attributes:true,attributeFilter:['data-homeward-ready']});reveal();draw();
